
import { DpiImage, VIcon } from '@/ui'
import { getUID } from '@/core/utils'
import { watchlaterList, toggleWatchlater } from '@/components/video/watchlater'

/*
  ============
  祖 传 代 码
  ============
*/
export default {
  // props: ['data', 'orientation'],
  components: {
    DpiImage,
    VIcon,
  },
  props: {
    data: {
      type: Object,
      required: true,
    },
    orientation: {
      type: String,
      // 'vertical'可以竖过来
      default: 'horizontal',
    },
    showStats: {
      type: Boolean,
      default: true,
    },
    isNew: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      watchlaterList,
      upFaceUrl: '',
      danmakuCount: '',
      like: '',
      coins: '',
      favorites: '',
      dynamic: '',
      topics: [],
      upID: 0,
      epID: 0,
      cooperation: [],
      pubTime: 0,
      pubTimeText: '',
      ...lodash.omit(this.data, 'watchlater'),
      watchlaterInit: this.data.watchlater,
      statsIconSize: 14,
    }
  },
  computed: {
    vertical() {
      return this.orientation === 'vertical'
    },
    watchlater() {
      if (getUID() && this.watchlaterInit !== null) {
        return this.watchlaterList.includes(this.aid)
      }
      return null
    },
    reversedCooperation() {
      return [...this.cooperation].reverse().slice(0, 3)
    },
  },
  methods: {
    toggleWatchlater,
  },
}
